.tel{
  position: fixed;
  bottom: 110px;
  right: 38px;
}
::v-deep .el-textarea__inner{
  font-size: 15px;
}
.description{
   ::v-deep .el-textarea__inner{
    min-height: 80px !important;
   }
}
.question_form {
  position: relative;
  height: 100%;
  box-shadow: 0 4px 25px 0 #e9f0ff;
  .back_btn {
    position: absolute;
    top: 0;
    left: 20px;
  }
  .form_title {
    text-align: center;
    margin-bottom: 20px;
  }
  .form_content {
    margin: 0 115px;
    height: calc(100% - 68px - 60px);
    margin-bottom: 15px;
    padding-right: 10px;
    overflow: auto;
    ::v-deep .el-input__inner {
      border-color: #93b8ff;
      height: 45px;
      font-size: 15px;
    }
    ::v-deep .el-form-item__label {
      line-height: 45px;
      color: #333;
    }
  }
  .dialogHieght {
    height: 67vh;
  }
  .btn_box {
    text-align: center;
  }
}
::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}
::v-deep ::-webkit-scrollbar-button {
  display: none;
}
::-webkit-scrollbar-thumb {
  background: #bed4ff;
  border-radius: 3px;
}
::-webkit-scrollbar-track {
  margin: 5px;
}
